Definition D_main_cells : list (Z * nat) :=
  [(0x123c50%Z, 8%nat); (0x143fb8%Z, 8%nat); (0x144018%Z, 8%nat); (0x143fe0%Z, 8%nat); (0x143fa8%Z, 8%nat); (0x143fa0%Z, 8%nat); (0x143d48%Z, 8%nat); (0x143d58%Z, 8%nat); (0x143d50%Z, 8%nat); (0x143fc8%Z, 8%nat); (0x143fd0%Z, 8%nat); (0x123d30%Z, 8%nat); (0x123d18%Z, 8%nat); (0x123c58%Z, 8%nat); (0x143fb0%Z, 1%nat); (0x123c80%Z, 4%nat); (0x123c78%Z, 4%nat); (0x123cf0%Z, 8%nat); (0x123cd0%Z, 8%nat); (0x123c60%Z, 8%nat); (0x123c68%Z, 8%nat); (0x123c70%Z, 8%nat); (0x143f90%Z, 4%nat); (0x143f94%Z, 4%nat); (0x143f91%Z, 1%nat); (0x123d10%Z, 8%nat); (0x113a10%Z, 1%nat)].

Definition range_disjoint_b (a : Z) (n : nat) (c : Z * nat) : bool :=
  ((a + Z.of_nat n <=? fst c) || (fst c + Z.of_nat (snd c) <=? a))%Z.

Definition D_main_missb (a : Z) (n : nat) : bool :=
  forallb (range_disjoint_b a n) D_main_cells && (0 <=? a)%Z && (a + Z.of_nat n <=? 0x145000)%Z.

(* [comment removed for export] *)
Definition djw (P : Prop) : Prop := P.

Section VP1. Context {fx : FPState}.   (* [comment removed for export] *)
Lemma range_disjoint_djw : forall a n c,
  range_disjoint_b a n c = true ->
  djw (a + Z.of_nat n <= fst c \/ fst c + Z.of_nat (snd c) <= a)%Z.
Proof.
